import{_ as l,a0 as o,w as p,s as r,ao as u,I as a,x as t,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"基礎：在 Linux 終端中移動文件 | LCTT x X-CMD","titleTemplate":false,"description":"基礎：在 Linux 終端中移動文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基礎：在 Linux 終端中移動文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基礎：在 Linux 終端中移動文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210804 Move files in the Linux terminal","title":"基礎：在 Linux 終端中移動文件","tag":"202108","desc":""},"relativePath":"202108/20210804 Move files in the Linux terminal.md","filePath":"[post].md"}'),d={name:"202108/20210804 Move files in the Linux terminal.md"};function m(x,e,f,g,h,k){const s=o("Link");return p(),r("div",null,[e[15]||(e[15]=u(`<h1 id="基礎-在-linux-終端中移動文件" tabindex="-1">基礎：在 Linux 終端中移動文件 <a class="header-anchor" href="#基礎-在-linux-終端中移動文件" aria-label="Permalink to “基礎：在 Linux 終端中移動文件”">​</a></h1><blockquote><p>使用 mv 命令將一個文件從一個位置移動到另一個位置。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/13/112248lnal8a0qz50zqzld.jpg" alt=""></p><p>要在有圖形界面的計算機上移動一個文件，你要打開該文件當前所在的文件夾，然後打開另一個窗口導航到你想把文件移到的文件夾。最後，你把文件從一個窗口拖到另一個窗口。</p><p>要在終端中移動文件，你可以使用 <code>mv</code> 命令將文件從一個位置移動到另一個位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv example.txt ~/Documents</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls ~/Documents</span></span>
<span class="line"><span>example.txt</span></span></code></pre></div><p>在這個例子中，你已經把 <code>example.txt</code> 從當前文件夾移到了主目錄下的 <code>Documents</code> 文件夾中。</p><p>只要你知道一個文件在 <em>哪裏</em>，又想把它移到 <em>哪裏</em> 去，你就可以把文件從任何地方移動到任何地方，而不管你在哪裏。與在一系列窗口中瀏覽你電腦上的所有文件夾以找到一個文件，然後打開一個新窗口到你想讓該文件去的地方，再拖動該文件相比，這可以大大節省時間。</p><p>默認情況下，<code>mv</code> 命令完全按照它被告知的那樣做：它將一個文件從一個位置移動到另一個位置。如果在目標位置已經存在一個同名的文件，它將被覆蓋。為了防止文件在沒有警告的情況下被覆蓋，請使用 <code>--interactive</code>（或簡寫 <code>-i</code>）選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv -i example.txt ~/Documents</span></span>
<span class="line"><span>mv: overwrite &#39;/home/tux/Documents/example.txt&#39;?</span></span></code></pre></div><hr>`,11)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),n(s,{href:"https://opensource.com/article/21/8/move-files-linux"},{default:i(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/21/8/move-files-linux",-1)])]),_:1})]),a("p",null,[e[6]||(e[6]=t("作者：",-1)),n(s,{href:"https://opensource.com/users/seth"},{default:i(()=>[...e[2]||(e[2]=[t("Seth Kenlon",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const c=l(d,[["render",m]]);export{v as __pageData,c as default};
